```go
// TestPostCommit_StaleEndedSession_ForceCondensed verifies that an ENDED
// session older than stalenessThreshold with FilesTouched but no commit
// overlap is force-condensed to prevent unbounded accumulation.
// This is the safety net for cases where eager-condense-on-stop failed.
func TestPostCommit_StaleEndedSession_ForceCondensed(t *testing.T) {
	dir := setupGitRepo(t)
	t.Chdir(dir)

	repo, err := git.PlainOpen(dir)
	require.NoError(t, err)

	s := &ManualCommitStrategy{}

	// Create ENDED session with:
	// - FilesTouched pointing at files NOT in the commit
	// - EndedAt > 1 hour ago (past staleness threshold)
	// - StepCount > 0 (uncondensed data)
	// - Shadow branch with transcript data
	sessionID := "stale-ended-session"
	// ... set up session with shadow branch containing transcript data
	// Set EndedAt to 2 hours ago
	endedAt := time.Now().Add(-2 * time.Hour)

	// Create an unrelated commit with checkpoint trailer
	// ... (no overlap with session's FilesTouched)

	// Run PostCommit
	err = s.PostCommit(context.Background())
	require.NoError(t, err)

	// Verify: session was force-condensed
	state, err := s.loadSessionState(context.Background(), sessionID)
	require.NoError(t, err)
	assert.Equal(t, 0, state.StepCount, "StepCount should be reset")
	assert.Empty(t, state.FilesTouched, "FilesTouched should be cleared")
	assert.True(t, state.FullyCondensed, "should be marked FullyCondensed")
}

// TestPostCommit_RecentEndedSession_NotForceCondensed verifies that an ENDED
// session within the staleness threshold is NOT force-condensed — the user
// may still commit those files.
func TestPostCommit_RecentEndedSession_NotForceCondensed(t *testing.T) {
	// Same setup as above but EndedAt = 5 minutes ago
	// Verify: session is NOT force-condensed (StepCount unchanged)
}
```

