- [ ] **Step 1: Write the integration test**

This test uses the existing `TestEnv` and `HookRunner` infrastructure from `integration_test/hooks.go`. The pattern mirrors `TestHookRunner_SimulateStop_SubagentOnlyChanges` but creates MULTIPLE subagent sessions that end without their files being committed.

```go
//go:build integration

package integration_test

import (
	"testing"
	"time"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

// TestSubagentAccumulation_Issue591 reproduces the exact scenario from GitHub
// issue #591: Claude Code spawns multiple subagents via the Agent tool, each
// gets its own Entire session. The parent session commits the work, but the
// subagent sessions' FilesTouched never overlap with any commit. Without the
// fix, these zombie sessions persist in ENDED state and are re-processed on
// every future PostCommit at ~60-100ms each.
//
// This test verifies:
// 1. Eager condense on session stop: subagent sessions are condensed immediately
// 2. PostCommit skips FullyCondensed sessions (no linear overhead)
// 3. Force-condense safety net: stale sessions missed by eager condense are
//    cleaned up within one commit after the staleness threshold
func TestSubagentAccumulation_Issue591(t *testing.T) {
	t.Parallel()
	env := NewTestEnv(t)

	// ========================================
	// Phase 1: Parent session starts and spawns subagents
	// ========================================
	t.Log("Phase 1: Simulating parent session with subagent spawning")

	parentSession := env.NewSession()
	err := env.SimulateUserPromptSubmit(parentSession.ID)
	require.NoError(t, err)

	// Create N subagent sessions (simulating Claude Code's Agent tool)
	// Each subagent modifies a unique file, then stops
	numSubagents := 5
	for i := range numSubagents {
		subSession := env.NewSessionWithID(fmt.Sprintf("subagent-%d", i))

		// Subagent starts
		err := env.SimulateUserPromptSubmit(subSession.ID)
		require.NoError(t, err)

		// Subagent writes a file
		subFile := fmt.Sprintf("subagent_work_%d.go", i)
		env.WriteFile(subFile, fmt.Sprintf("package main\nfunc Sub%d() {}\n", i))

		// Build subagent transcript with Write tool call
		transcript := NewTranscriptBuilder()
		transcript.AddUserMessage(fmt.Sprintf("Create function Sub%d", i))
		absPath := filepath.Join(env.RepoDir, subFile)
		toolID := transcript.AddToolUse("Write", absPath, fmt.Sprintf("package main\nfunc Sub%d() {}\n", i))
		transcript.AddToolResult(toolID)
		transcript.AddAssistantMessage("Done.")
		require.NoError(t, transcript.WriteToFile(subSession.TranscriptPath))

		// Subagent stops — this should trigger eager condense
		err = env.SimulateStop(subSession.ID, subSession.TranscriptPath)
		require.NoError(t, err)

		// Verify: subagent session should be FullyCondensed after stop
		state, err := env.GetSessionState(subSession.ID)
		require.NoError(t, err)
		if state != nil {
			assert.True(t, state.FullyCondensed,
				"subagent session %d should be FullyCondensed after stop (eager condense)", i)
			assert.Equal(t, 0, state.StepCount,
				"subagent session %d StepCount should be 0 after eager condense", i)
		}
	}

	// ========================================
	// Phase 2: Parent session commits (unrelated to subagent files)
	// ========================================
	t.Log("Phase 2: Parent session commits unrelated file")

	env.WriteFile("parent_work.go", "package main\nfunc ParentWork() {}\n")
	env.GitAdd("parent_work.go")
	env.GitCommitWithShadowHooks("Parent's commit", "parent_work.go")

	// ========================================
	// Phase 3: Verify PostCommit didn't waste time on subagent sessions
	// ========================================
	t.Log("Phase 3: Verifying subagent sessions are still FullyCondensed (skipped by PostCommit)")

	for i := range numSubagents {
		sessionID := fmt.Sprintf("subagent-%d", i)
		state, err := env.GetSessionState(sessionID)
		require.NoError(t, err)
		if state != nil {
			assert.True(t, state.FullyCondensed,
				"subagent session %d should still be FullyCondensed after PostCommit", i)
		}
	}

	// ========================================
	// Phase 4: Make more commits to verify no accumulation
	// ========================================
	t.Log("Phase 4: Making additional commits to verify no accumulation overhead")

	for j := range 3 {
		file := fmt.Sprintf("follow_up_%d.go", j)
		env.WriteFile(file, fmt.Sprintf("package main\nfunc FollowUp%d() {}\n", j))
		env.GitAdd(file)
		env.GitCommitWithShadowHooks(fmt.Sprintf("Follow-up commit %d", j), file)
	}

	// All subagent sessions should still be FullyCondensed — not re-processed
	for i := range numSubagents {
		sessionID := fmt.Sprintf("subagent-%d", i)
		state, err := env.GetSessionState(sessionID)
		require.NoError(t, err)
		if state != nil {
			assert.True(t, state.FullyCondensed,
				"subagent session %d should remain FullyCondensed after multiple commits", i)
		}
	}

	t.Log("Test completed: no subagent session accumulation observed")
}
```

Note: Adapt helper names (`NewSessionWithID`, `SimulateUserPromptSubmit`, `GitCommitWithShadowHooks`, etc.) to match the exact signatures in `integration_test/hooks.go`. Check `NewTestEnv` vs `NewRepoWithCommit` — use whichever provides the session lifecycle hooks. You may need to use `NewFeatureBranchEnv` if that's the one with full hook simulation.

